<?php

namespace Database\Seeders;

use App\Models\Location;
use Illuminate\Database\Seeder;

/**
 * Şehir sayfaları.
 *
 * Her şehrin metni o pazara özgü yazıldı: Girne'de turizm ve yabancı müşteri,
 * Magosa'da öğrenci nüfusu, Bursa'da bayi ağı… Aynı metnin şehir adı
 * değiştirilmiş kopyaları arama motorlarınca kapı sayfası (doorway page)
 * sayılır ve cezalandırılır.
 *
 * Metinler pazar gözlemi ve hizmet tanımıdır; uydurma referans, müşteri sayısı
 * ya da başarı iddiası içermez.
 */
class LocationSeeder extends Seeder
{
    public function run(): void
    {
        foreach ($this->locations() as $i => $location) {
            Location::query()->updateOrCreate(
                ['slug' => $location['slug']],
                $location + ['sort_order' => $i + 1, 'is_active' => true],
            );
        }
    }

